(()=>{const photos=[...document.querySelectorAll('.rental-gallery-photo')],box=document.getElementById('rentalLightbox');if(!box||!photos.length)return;const img=document.getElementById('rentalLightboxImage'),caption=document.getElementById('rentalPhotoCaption');let index=0;const show=i=>{index=(i+photos.length)%photos.length;const source=photos[index];img.src=source.querySelector('img').src;img.alt=source.querySelector('img').alt;caption.textContent=source.querySelector('span').textContent.replace('↗','').trim()};const close=()=>{box.hidden=true;document.body.style.overflow='';photos[index].focus()};photos.forEach((p,i)=>p.addEventListener('click',()=>{show(i);box.hidden=false;document.body.style.overflow='hidden';document.getElementById('rentalLightboxClose').focus()}));document.getElementById('rentalLightboxClose').addEventListener('click',close);document.getElementById('rentalPhotoPrev').addEventListener('click',()=>show(index-1));document.getElementById('rentalPhotoNext').addEventListener('click',()=>show(index+1));box.addEventListener('click',e=>{if(e.target===box)close()});document.addEventListener('keydown',e=>{if(box.hidden)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')show(index+1);if(e.key==='ArrowLeft')show(index-1)})})();
